def next_smallest_palindrome(n):
    def is_palindrome(num):
        return str(num) == str(num)[::-1]

    def increment_palindrome(num):
        str_num = str(num)
        length = len(str_num)
        if length == 1:
            return num + 1
        mid = length // 2
        if length % 2 == 0:
            left_half = str_num[:mid]
            right_half = str_num[mid:]
        else:
            left_half = str_num[:mid]
            right_half = str_num[mid+1:]

        if left_half > right_half[::-1]:
            next_left_half = str(int(left_half) + 1)
            next_right_half = next_left_half[::-1]
            return int(next_left_half + next_right_half)
        else:
            next_left_half = left_half
            next_right_half = next_left_half[::-1]
            return int(next_left_half + next_right_half)

    n = int(n)
    if n < 10:
        return n + 1

    next_palindrome = n + 1
    while not is_palindrome(next_palindrome):
        next_palindrome += 1

    return next_palindrome

