def search(arr):
    left, right = 0, len(arr) - 1

    while left < right:
        mid = (left + right) // 2

        # Check if mid is even or odd index
        if mid % 2 == 0:
            # If mid is even, compare mid and mid + 1
            if arr[mid] == arr[mid + 1]:
                left = mid + 2
            else:
                right = mid
        else:
            # If mid is odd, compare mid and mid - 1
            if arr[mid] == arr[mid - 1]:
                left = mid + 1
            else:
                right = mid - 1

