def sum_divisors(n):
    """Returns the sum of proper divisors of n."""
    divisors_sum = 1
    for i in range(2, int(n**0.5) + 1):
        if n % i == 0:
            divisors_sum += i
            if i != n // i:
                divisors_sum += n // i
    return divisors_sum

def amicable_numbers_sum(limit):
    """Returns the sum of all amicable numbers up to the specified limit."""
    amicable_sum = 0
    for a in range(2, limit + 1):
        b = sum_divisors(a)
        if b > a and b <= limit and sum_divisors(b) == a:
