def is_majority(arr, n, element):
    # Calculate the threshold for the majority element
    majority_threshold = n // 2

    # Use binary search to find the first and last occurrence of the element
    def binary_search(arr, target, left, right, find_first):
        while left <= right:
            mid = (left + right) // 2
            if arr[mid] == target:
                if find_first:
                    if mid == left or arr[mid - 1] != target:
                        return mid
                    else:
                        right = mid - 1
                else:
                    if mid == right or arr[mid + 1] != target:
                        return mid
                    else:
                        left = mid + 1
            elif arr[mid] < target:
                left = mid + 1
            else:
                right = mid - 1
        return -1

