def count_bidirectional(tuples):
    seen = {}
    count = 0

    for t in tuples:
        reversed_t = t[::-1]
        if reversed_t in seen:
            count += 1
            if seen[reversed_t] > 0:
                seen[reversed_t] -= 1
            else:
                del seen[reversed_t]
        else:
